@import "@fontsource-variable/mona-sans";
@import "@fontsource-variable/geist-mono";

/* Light (faithful): linen paper (#f9f7f4), charcoal text (#202020), white cards, a merlot
   first screen (#3b1515), sand buttons and hairlines (#dcd2ba), tan emphasis (#c3b39c) and a
   crimson accent (#8e1717) for small marks. */
:root {
  --background: #f9f7f4;
  --foreground: #202020;
  --card: #ffffff;
  --card-foreground: #202020;
  --popover: #ffffff;
  --popover-foreground: #202020;
  --primary: #3b1515;
  --primary-foreground: #f9f7f4;
  --secondary: #dcd2ba;
  --secondary-foreground: #202020;
  --muted: #f3f1ea;
  --muted-foreground: #626160;
  --accent: #f3f1ea;
  --accent-foreground: #202020;
  --destructive: #b42318;
  --destructive-foreground: #f9f7f4;
  --border: #dcd2ba;
  --input: #dcd2ba;
  --ring: #c3b39c;
  --highlight: #c3b39c;
  --highlight-foreground: #202020;
  --glow: #8e1717;
  --chart-1: #3b1515;
  --chart-2: #8e1717;
  --chart-3: #c3b39c;
  --chart-4: #303b46;
  --chart-5: #dcd2ba;
  --sidebar: #f3f1ea;
  --sidebar-foreground: #202020;
  --sidebar-primary: #3b1515;
  --sidebar-primary-foreground: #f9f7f4;
  --sidebar-accent: #dcd2ba;
  --sidebar-accent-foreground: #202020;
  --sidebar-border: #dcd2ba;
  --sidebar-ring: #c3b39c;

  --typeface-body: "Mona Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Mona Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.1875rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.25rem, 3.5vw, 3.125rem);
  --section-y: clamp(5.5rem, 3rem + 7.5vw, 9rem);
}

/* Dark: a warm near-black page, merlot-brown cards, linen text; the hero surface is a lighter
   merlot so it still reads as its own screen. Sand stays the button colour. */
.dark {
  --background: #161010;
  --foreground: #f3efe8;
  --card: #221817;
  --card-foreground: #f3efe8;
  --popover: #221817;
  --popover-foreground: #f3efe8;
  --primary: #4a1c1c;
  --primary-foreground: #f9f7f4;
  --secondary: #dcd2ba;
  --secondary-foreground: #202020;
  --muted: #2a1f1d;
  --muted-foreground: #b4ab9f;
  --accent: #2a1f1d;
  --accent-foreground: #f3efe8;
  --destructive: #e0574b;
  --destructive-foreground: #161010;
  --border: #dcd2ba33;
  --input: #dcd2ba40;
  --ring: #c3b39c;
  --highlight: #c9b89f;
  --highlight-foreground: #202020;
  --glow: #d9675b;
  --chart-1: #c9b89f;
  --chart-2: #d9675b;
  --chart-3: #dcd2ba;
  --chart-4: #8fa1b3;
  --chart-5: #7a3a3a;
  --sidebar: #1c1413;
  --sidebar-foreground: #f3efe8;
  --sidebar-primary: #c9b89f;
  --sidebar-primary-foreground: #202020;
  --sidebar-accent: #2a1f1d;
  --sidebar-accent-foreground: #f3efe8;
  --sidebar-border: #dcd2ba33;
  --sidebar-ring: #c3b39c;
}
